mapper.select:
SELECT CD.*, CI.CustName AS CustName
FROM shopion.tPrfCustDeliAddr CD
INNER JOIN shopion.tPrfCust CI ON CD.CustId = CI.CustId

    AND CI.ChnlCode = #{pChnlCode}
    AND CI.CustName LIKE CONCAT('%',#{pCustName},'%')
    AND CI.LoginId LIKE CONCAT('%',#{pLoginId},'%')
    AND CI.CustId = #{pCustId}

ORDER BY ${sidx} ${sord}

SELECT *
FROM shopion.tPrfCustDeliAddr
WHERE CustId = #{custId}
AND DeliAddrNo = #{deliAddrNo}
